import '../styles/styleguide.css'

(function () {
  'use strict';

  /* ---- mobile navigation ---- */
  var burger = document.getElementById('burger');
  var nav = document.getElementById('nav');
  var backdrop = document.getElementById('backdrop');
  function setNav(open) {
    nav.classList.toggle('open', open);
    backdrop.classList.toggle('on', open);
    burger.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  burger.addEventListener('click', function () { setNav(!nav.classList.contains('open')); });
  backdrop.addEventListener('click', function () { setNav(false); });
  nav.addEventListener('click', function (e) {
    if (e.target.tagName === 'A' && window.innerWidth <= 900) setNav(false);
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setNav(false); });

  /* ---- scrollspy ---- */
  var links = Array.prototype.slice.call(nav.querySelectorAll('a[href^="#"]'));
  var targets = links.map(function (a) {
    return document.getElementById(a.getAttribute('href').slice(1));
  }).filter(Boolean);
  function spy() {
    var pos = window.scrollY + 90, current = targets[0];
    for (var i = 0; i < targets.length; i++) {
      if (targets[i].offsetTop <= pos) current = targets[i];
    }
    links.forEach(function (a) {
      a.classList.toggle('on', a.getAttribute('href') === '#' + (current && current.id));
    });
  }
  window.addEventListener('scroll', spy, { passive: true });
  spy();

  /* ---- sidebar filter ---- */
  var search = document.getElementById('search');
  search.addEventListener('input', function () {
    var q = search.value.trim().toLowerCase();
    links.forEach(function (a) {
      var label = a.textContent.toLowerCase();
      var comp = document.getElementById(a.getAttribute('href').slice(1));
      var inComp = comp ? comp.textContent.toLowerCase().indexOf(q) !== -1 : false;
      var show = !q || label.indexOf(q) !== -1 || inComp;
      a.style.display = show ? '' : 'none';
    });
  });

  /* ---- copy buttons ---- */
  document.querySelectorAll('.codewrap > button').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var pre = btn.parentNode.querySelector('pre');
      var text = pre.innerText;
      function done() {
        btn.textContent = 'Copied';
        btn.classList.add('done');
        setTimeout(function () { btn.textContent = 'Copy'; btn.classList.remove('done'); }, 1600);
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, done);
      } else {
        var ta = document.createElement('textarea');
        ta.value = text; document.body.appendChild(ta); ta.select();
        try { document.execCommand('copy'); } catch (e) {}
        document.body.removeChild(ta); done();
      }
    });
  });

  /* ---- lazy thumbnail demo ---- */
  document.querySelectorAll('[data-sg-thumb]').forEach(function (img) {
    img.addEventListener('click', function () {
      var url = img.getAttribute('data-sg-thumb');
      var pre = new Image();
      pre.onload = function () { img.src = url; img.removeAttribute('data-sg-thumb'); };
      pre.src = url;
    });
  });

  /* ---- Kapish dark theme demo ---- */
  var kpToggle = document.getElementById('kp-theme-toggle');
  if (kpToggle) {
    kpToggle.addEventListener('click', function () {
      var t = document.getElementById('kp-theme-target');
      var on = t.classList.toggle('is-dark');
      kpToggle.textContent = on ? 'Toggle light theme' : 'Toggle dark theme';
    });
  }

  /* ---- Finobe v2 theme matrix demo ---- */
  var state = { night: false, branding: 'finobe', logo: 'default', season: null, upsidedown: false, gary: false };
  var FB = 'https://raw.githubusercontent.com/finobenet/finobenet/main/public/s/img/';
  function logoFor() {
    if (state.season === 'halloween') return FB + 'halloween3.png';
    if (state.season === 'xmas') return FB + 'finobe_xmas.png';
    if (state.logo === 'v1') return FB + 'BUSY.png';
    if (state.logo === 'v2') return FB + 'finnobe3.png';
    return FB + (state.branding === 'finobe' ? 'finnobe3logo.png' : 'logo.png');
  }
  function renderFb2() {
    var root = document.getElementById('fb2-root');
    var nav = document.getElementById('fb2-nav');
    var logo = document.getElementById('fb2-logo');
    var name = state.branding === 'finobe' ? 'Finobe' : 'Aesthetiful';
    root.classList.toggle('night', state.night || state.gary);
    nav.classList.toggle('dark', state.night || state.gary);
    nav.classList.toggle('navbar-light-halloween', state.season === 'halloween' && !state.night);
    logo.src = logoFor();
    logo.alt = name;
    document.getElementById('fb2-name').textContent = name;
    document.getElementById('fb2-name2').textContent = name;
    document.getElementById('fb2-gary').style.display = state.gary ? '' : 'none';
    root.classList.toggle('upsidedown', state.upsidedown);
    document.getElementById('fb2-controls').querySelectorAll('button').forEach(function (b) {
      var k = b.getAttribute('data-fb2');
      var active = (k === 'night' && state.night) || (k === 'gary' && state.gary) ||
                   (k === 'upsidedown' && state.upsidedown) ||
                   (k === 'branding' && state.branding !== 'finobe') ||
                   (k === 'logo' && state.logo !== 'default') ||
                   (k === 'season' && state.season);
      b.style.background = active ? '#38c172' : '#455dd8';
      b.style.borderColor = b.style.background;
    });
  }
  document.querySelectorAll('#fb2-controls button').forEach(function (b) {
    b.addEventListener('click', function () {
      var k = b.getAttribute('data-fb2');
      if (k === 'night') state.night = !state.night;
      else if (k === 'gary') state.gary = !state.gary;
      else if (k === 'upsidedown') state.upsidedown = !state.upsidedown;
      else if (k === 'branding') state.branding = state.branding === 'finobe' ? 'aesthetiful' : 'finobe';
      else if (k === 'logo') state.logo = state.logo === 'default' ? 'v1' : (state.logo === 'v1' ? 'v2' : 'default');
      else if (k === 'season') state.season = state.season === null ? 'halloween' : (state.season === 'halloween' ? 'xmas' : null);
      renderFb2();
    });
  });
  if (document.getElementById('fb2-root')) renderFb2();

  /* ---- snowfall demo, with a reduced-motion guard ---- */
  var snowHost = document.getElementById('sg-snow');
  var snowToggle = document.getElementById('sg-snow-toggle');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (snowHost) {
    var glyphs = ['\u2745', '\u2746'], n = 12;
    for (var i = 0; i < n; i++) {
      var d = document.createElement('div');
      d.className = 'snowflake';
      d.textContent = glyphs[i % 2];
      d.style.left = (i * 8 + 2) + '%';
      d.style.animationDelay = (i * 0.8) + 's, ' + (i * 0.3) + 's';
      d.style.animationPlayState = 'paused, paused';
      snowHost.appendChild(d);
    }
    if (reduce && snowToggle) {
      snowToggle.checked = false;
      snowToggle.disabled = true;
      snowToggle.parentNode.innerHTML += ' <em>&mdash; disabled: your system requests reduced motion</em>';
    }
    function setSnow(on) {
      snowHost.querySelectorAll('.snowflake').forEach(function (f) {
        f.style.animationPlayState = on ? 'running, running' : 'paused, paused';
      });
    }
    setSnow(!reduce);
    if (snowToggle) snowToggle.addEventListener('change', function () { setSnow(snowToggle.checked); });
  }
})();



