(function(){
const manifest=window.COMPLETE_ASSET_MANIFEST;if(!manifest)return;const all=manifest.flatMap(p=>p.files.filter(f=>f.kind==='image'&&!/\.svg$/i.test(f.path)).map(f=>({...f,project:p.name}))),results=document.getElementById('fusion-asset-results'),search=document.getElementById('fusion-asset-search'),project=document.getElementById('fusion-asset-project'),canvas=document.getElementById('fusion-canvas'),ctx=canvas.getContext('2d');let chosen=[null,null],slot=0,limit=60,baked=false;[...new Set(all.map(x=>x.project))].forEach(x=>project.add(new Option(x,x)));
function find(){let q=search.value.toLowerCase(),found=all.filter(x=>(!project.value||x.project===project.value)&&(!q||(x.path+' '+x.project).toLowerCase().includes(q)));results.innerHTML=found.slice(0,limit).map(x=>'<button class="asset-choice" data-u="'+encodeURIComponent(x.url)+'" data-p="'+encodeURIComponent(x.path)+'"><img loading="lazy" src="'+x.url+'"><span>'+x.path.split('/').pop()+'</span></button>').join('');results.querySelectorAll('button').forEach(b=>b.onclick=()=>pick({url:decodeURIComponent(b.dataset.u),path:decodeURIComponent(b.dataset.p)}));document.getElementById('fusion-asset-more').hidden=found.length<=limit}search.oninput=()=>{limit=60;find()};project.onchange=()=>{limit=60;find()};document.getElementById('fusion-asset-more').onclick=()=>{limit+=60;find()};
function pick(o){let i=slot;chosen[i]=o;slot=1-slot;show();baked=false}function show(){chosen.forEach((x,i)=>{let el=document.getElementById('fusion-slot-'+(i?'b':'a'));el.classList.toggle('filled',!!x);el.innerHTML=x?'<b>Asset '+(i?'B':'A')+'</b><img src="'+x.url+'"><span>'+x.path+'</span>':'<b>Asset '+(i?'B':'A')+'</b><span>Select an image below</span>'})}
function load(x){return new Promise((ok,no)=>{let i=new Image();i.crossOrigin='anonymous';i.onload=()=>ok(i);i.onerror=no;i.src=x.url})}function cover(c,i,w,h){let q=Math.max(w/i.width,h/i.height),dw=i.width*q,dh=i.height*q;c.drawImage(i,(w-dw)/2,(h-dh)/2,dw,dh)}
async function fuse(){if(!chosen[0]||!chosen[1])return alert('Select exactly two source assets first.');let size=+document.getElementById('asset-fusion-size').value,method=document.getElementById('asset-fusion-method').value,mix=+document.getElementById('asset-fusion-mix').value/100;canvas.width=canvas.height=size;let [a,b]=await Promise.all(chosen.map(load));let ca=document.createElement('canvas'),cb=document.createElement('canvas');ca.width=cb.width=size;ca.height=cb.height=size;cover(ca.getContext('2d'),a,size,size);cover(cb.getContext('2d'),b,size,size);ctx.clearRect(0,0,size,size);ctx.drawImage(ca,0,0);if(['multiply','screen','difference'].includes(method)){ctx.globalAlpha=mix;ctx.globalCompositeOperation=method;ctx.drawImage(cb,0,0)}else if(method==='silhouette'){let t=document.createElement('canvas');t.width=t.height=size;let tc=t.getContext('2d');tc.drawImage(ca,0,0);tc.globalCompositeOperation='source-in';tc.drawImage(cb,0,0);ctx.globalAlpha=mix;ctx.drawImage(t,0,0)}else{ctx.drawImage(cb,0,0);ctx.globalCompositeOperation='destination-in';let g;if(method==='radial'){g=ctx.createRadialGradient(size/2,size/2,0,size/2,size/2,size*.7);g.addColorStop(Math.max(0,mix-.15),'rgba(0,0,0,1)');g.addColorStop(Math.min(1,mix+.15),'rgba(0,0,0,0)')}else if(method==='gradient'){g=ctx.createLinearGradient(0,0,size,0);g.addColorStop(Math.max(0,mix-.15),'rgba(0,0,0,0)');g.addColorStop(Math.min(1,mix+.15),'rgba(0,0,0,1)')}else{let pat=document.createElement('canvas'),pc=pat.getContext('2d'),unit=method==='checker'?48:24;pat.width=pat.height=unit*2;pc.fillStyle='#000';if(method==='checker'){pc.fillRect(0,0,unit,unit);pc.fillRect(unit,unit,unit,unit)}else pc.fillRect(0,0,unit,unit*2);g=ctx.createPattern(pat,'repeat')}ctx.fillStyle=g;ctx.fillRect(0,0,size,size);ctx.globalCompositeOperation='destination-over';ctx.drawImage(ca,0,0)}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';baked=true}
document.getElementById('fuse-assets').onclick=()=>fuse().catch(()=>alert('One original host blocked pixel access. Try another pair.'));document.getElementById('fusion-swap').onclick=()=>{chosen.reverse();show();baked=false};document.getElementById('fusion-random').onclick=()=>{let opts=['gradient','radial','checker','stripes','multiply','screen','difference','silhouette'],m=document.getElementById('asset-fusion-method');m.value=opts[Math.floor(Math.random()*opts.length)];document.getElementById('asset-fusion-mix').value=20+Math.floor(Math.random()*61);if(chosen[0]&&chosen[1])fuse()};document.getElementById('fusion-download').onclick=()=>{if(!baked)return alert('Fuse and bake the assets first.');let a=document.createElement('a');a.download='fused-asset.png';try{a.href=canvas.toDataURL('image/png');a.click()}catch(e){alert('The original asset host blocked PNG export.')}};document.getElementById('fusion-send-ui').onclick=()=>{if(!baked)return alert('Fuse and bake the assets first.');alert('The fused asset is ready. Download it, then use it in the exported hybrid UI.');};find();show();
})();


