window.CLIENT_RCC_REGISTRY=[{"id":"bb2015","year":"2015","label":"BubbaBlox 2015 bundle","client":"Client material in BubbaBlox source","clientUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021","rcc":"RCCService2015","rccUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/RCCService2015","source":"BubbaBlox v2","status":"bundled","notes":"RCC directory is explicitly versioned 2015. Confirm the exact client build/version hashes before use."},{"id":"bb2016","year":"2016","label":"BubbaBlox 2016 frontend/client family","client":"2016-roblox-main","clientUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/2016-roblox-main","rcc":"RCCService (unversioned)","rccUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/RCCService","source":"BubbaBlox v2","status":"inferred","notes":"The frontend names 2016, but the unversioned RCC directory requires hash/security-version validation."},{"id":"bb2017","year":"2017","label":"BubbaBlox 2017 pair","client":"2017 client family","clientUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021","rcc":"RCCService2017","rccUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/RCCService2017","source":"BubbaBlox v2","status":"bundled","notes":"Version-labeled RCC is bundled beside the project; exact client build remains to be selected."},{"id":"bb2018","year":"2018","label":"BubbaBlox 2018 pair","client":"2018 client family","clientUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021","rcc":"RCCService2018","rccUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/RCCService2018","source":"BubbaBlox v2","status":"bundled","notes":"Contains DevSettingsFile.json and ReflectionMetadata.xml. Match security versions and API behavior."},{"id":"bb2020","year":"2020","label":"BubbaBlox 2020 pair","client":"2020 client family","clientUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021","rcc":"RCCService2020","rccUrl":"https://github.com/harryzawg/bubbablox-v2/tree/2021/RCCService2020","source":"BubbaBlox v2","status":"bundled","notes":"Version-labeled RCC is present. Validate executable build date and protocol before deployment."},{"id":"hex2014","year":"2014","label":"Hexagon 2013/2014 stack","client":"Hexagon client/tooling","clientUrl":"https://github.com/suush-ii/hexagon-public/tree/main","rcc":"RCC integration source","rccUrl":"https://github.com/suush-ii/hexagon-public/tree/main/src/routes/(rcc)","source":"Hexagon","status":"inferred","notes":"Routes expose RCC security/hash integration, but the public tree is not a simple redistributable RCC/client binary pair."},{"id":"tadah2016","year":"2016","label":"Tadah / Kapish 2016 family","client":"Tadah launcher/client references","clientUrl":"https://github.com/Casenn05/Tadah-2014-Launcher-Decompiled-Source","rcc":"Not bundled in web repository","rccUrl":"https://github.com/conewasnthere/kapish-web-trunk","source":"Tadah / Kapish","status":"unknown","notes":"Do not assume launcher year or website branding identifies an RCC-compatible build."}];(function(){const d=window.CLIENT_RCC_REGISTRY,g=document.getElementById('compat-grid');if(!g)return;const q=document.getElementById('compat-search'),y=document.getElementById('compat-year'),src=document.getElementById('compat-source'),conf=document.getElementById('compat-confidence'),count=document.getElementById('compat-count'),plan=document.getElementById('planner-pair');const fav=new Set(JSON.parse(localStorage.getItem('rcc-favorites')||'[]'));const checks=['Confirm exact client executable build date','Record client SHA-256 hash','Record RCCService SHA-256 hash','Compare GetAllowedSecurityVersions response','Compare GetAllowedMD5Hashes response','Verify authentication ticket format','Verify place-launch/job request schema','Test rendering in an isolated environment','Document required API endpoints','Review repository license and redistribution rights'];[...new Set(d.map(x=>x.year))].sort().forEach(x=>y.add(new Option(x,x)));[...new Set(d.map(x=>x.source))].sort().forEach(x=>src.add(new Option(x,x)));d.forEach(x=>plan.add(new Option(x.label,x.id)));function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function draw(){let z=q.value.toLowerCase(),a=d.filter(x=>(!y.value||x.year===y.value)&&(!src.value||x.source===src.value)&&(!conf.value||x.status===conf.value)&&(!z||Object.values(x).join(' ').toLowerCase().includes(z)));count.textContent=a.length+' compatibility records';g.innerHTML=a.map(x=>`<article class="compat-card"><button class="compat-favorite ${fav.has(x.id)?'on':''}" data-fav="${x.id}">★</button><span class="compat-year">${esc(x.year)}</span><h3>${esc(x.label)}</h3><span class="compat-status status-${x.status}">${esc(x.status.toUpperCase())}</span><div class="compat-pair"><div class="compat-side"><b>Client</b><small>${esc(x.client)}</small></div><b>↔</b><div class="compat-side"><b>RCCService</b><small>${esc(x.rcc)}</small></div></div><p class="note">${esc(x.notes)}</p><div class="forge-actions"><a class="compat-link" target="_blank" href="${esc(x.clientUrl)}">Client source ↗</a><a class="compat-link" target="_blank" href="${esc(x.rccUrl)}">RCC source ↗</a></div></article>`).join('');g.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{fav.has(b.dataset.fav)?fav.delete(b.dataset.fav):fav.add(b.dataset.fav);localStorage.setItem('rcc-favorites',JSON.stringify([...fav]));draw()})}[q,y,src,conf].forEach(x=>x.addEventListener(x===q?'input':'change',draw));function checklist(){let id=plan.value,state=JSON.parse(localStorage.getItem('rcc-checks-'+id)||'{}');document.getElementById('planner-checklist').innerHTML=checks.map((x,i)=>`<li><label><input type="checkbox" data-i="${i}" ${state[i]?'checked':''}> ${x}</label></li>`).join('');document.querySelectorAll('#planner-checklist input').forEach(x=>x.onchange=()=>{state[x.dataset.i]=x.checked;localStorage.setItem('rcc-checks-'+id,JSON.stringify(state));summary(state)});summary(state)}function summary(st){let n=Object.values(st).filter(Boolean).length;document.getElementById('planner-summary').textContent=n+' of '+checks.length+' compatibility checks completed.'}plan.onchange=checklist;document.getElementById('planner-export').onclick=()=>{let pair=d.find(x=>x.id===plan.value),obj={project:document.getElementById('planner-name').value,pair,notes:document.getElementById('planner-notes').value,checks},a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download='client-rcc-plan.json';a.click();URL.revokeObjectURL(a.href)};draw();checklist()})();